style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
/* Don’t break icons or code */
  :root, html, body,
  body *:not(i[class*="icon"]):not([class*="fa-"]):not([class^="fa"])
        :not([class*="material-icons"]):not([class*="ti-"])
        :not(pre):not(code):not(kbd):not(samp) {
    font-synthesis: none !important;
    text-rendering: optimizeLegibility;
  }

  /* Default Latin/Cyrillic/Greek fallback */
  body {
    font-family:
      system-ui, "Segoe UI", Roboto, "Helvetica Neue", Arial,
      "Noto Sans", sans-serif !important;
  }

  /* Korean */
  :lang(ko) {
    font-family:
      "Noto Sans KR", "Apple SD Gothic Neo", "Pretendard Variable", "Pretendard",
      "Noto Sans CJK KR",
      system-ui, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
  }

  /* Japanese */
  :lang(ja) {
    font-family:
      "Noto Sans JP", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Yu Gothic UI",
      "Noto Sans CJK JP",
      system-ui, Roboto, "Helvetica Neue", Arial, sans-serif !important;
  }

  /* Simplified Chinese */
  :lang(zh-CN), :lang(zh-Hans) {
    font-family:
      "Noto Sans SC", "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei",
      "Noto Sans CJK SC",
      system-ui, Roboto, "Helvetica Neue", Arial, sans-serif !important;
  }

  /* Traditional Chinese */
  :lang(zh-TW), :lang(zh-HK), :lang(zh-Hant) {
    font-family:
      "Noto Sans TC", "PingFang TC", "Microsoft JhengHei UI", "Microsoft JhengHei",
      "Noto Sans CJK TC",
      system-ui, Roboto, "Helvetica Neue", Arial, sans-serif !important;
  }

  /* Arabic */
  :lang(ar), :lang(fa), :lang(ur) {
    font-family:
      "Noto Naskh Arabic", "Amiri", "Noto Sans Arabic",
      system-ui, Arial, sans-serif !important;
    font-variant-ligatures: common-ligatures;
  }

  /* Devanagari (Hindi, Marathi, Nepali…) */
  :lang(hi), :lang(mr), :lang(ne) {
    font-family:
      "Noto Sans Devanagari", "Hind", "Mukta",
      system-ui, Arial, sans-serif !important;
  }

  /* Thai */
  :lang(th) {
    font-family:
      "Noto Sans Thai", "Sarabun",
      system-ui, Arial, sans-serif !important;
  }

  /* Hebrew */
  :lang(he) {
    font-family:
      "Noto Sans Hebrew", "Rubik",
      system-ui, Arial, sans-serif !important;
  }

  /* Monospace stays monospace */
  pre, code, kbd, samp {
    font-family:
      ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono",
      "Noto Sans Mono", monospace !important;
  }

  /* Emoji fallback so CJK stacks don’t swallow them */
  .emoji, :root {
    --emoji-stack: "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji";
  }
}
